contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 receiverBalBefore = c.balanceOf(to);
        require(amount <= senderBalBefore);

        bool success = c.transfer(to, amount);
        require(success);

        uint256 senderBalAfter = c.balanceOf(address(this));
        uint256 receiverBalAfter = c.balanceOf(to);

        assert(senderBalAfter == senderBalBefore - amount && receiverBalAfter == receiverBalBefore + amount);
    }

    receive() external payable {}
}

